<?php
declare(strict_types=1);
require_once __DIR__.'/vendor.php';
function slugify(string $value): string {$value=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$value)?:$value;$value=strtolower(trim(preg_replace('/[^A-Za-z0-9]+/','-',$value),'-'));return $value!==''?$value:'product';}
function unique_product_slug(PDO $db,string $name,string $productId): string {$base=slugify($name);$slug=$base;for($i=0;$i<20;$i++){$stmt=$db->prepare('SELECT id FROM products WHERE slug=:slug AND id<>:id LIMIT 1');$stmt->execute(['slug'=>$slug,'id'=>$productId]);if(!$stmt->fetch())return $slug;$slug=$base.'-'.substr(str_replace('-','',$productId),0,8).($i?'-'.$i:'');}throw new RuntimeException('Could not generate product slug.');}
function product_snapshot(array $product): array {$fields=['name','slug','sku','category_id','subcategory_id','short_description','description','mrp','selling_price','gst_percent','material','craft_technique','dimensions','origin_state','gi_tag','care_instructions','tags_json','package_weight_grams','package_length_cm','package_width_cm','package_height_cm','processing_min_days','processing_max_days'];$snapshot=[];foreach($fields as $field)$snapshot[$field]=$product[$field]??null;return $snapshot;}
function vendor_product(string $productId,string $vendorId,bool $forUpdate=false): array {$stmt=get_db()->prepare('SELECT * FROM products WHERE id=:id AND vendor_id=:vendor LIMIT 1'.($forUpdate?' FOR UPDATE':''));$stmt->execute(['id'=>$productId,'vendor'=>$vendorId]);$product=$stmt->fetch();if(!$product)json_response(404,['success'=>false,'message'=>'Product not found.']);return $product;}
